package server

const indexHTML = `<!doctype html>
<html lang="de"><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta charset="utf-8"><title>NexusForge</title>
<style>body{font-family:system-ui,sans-serif;background:#101827;color:#f5f7ff;max-width:780px;margin:0 auto;padding:20px}h1{letter-spacing:.5px}p{color:#bac6db}.panel{background:#1c2a40;border:1px solid #374763;border-radius:15px;padding:15px;margin:12px 0}input,textarea,button{font:inherit;border-radius:9px;padding:12px;box-sizing:border-box}input,textarea{background:#0d1423;color:#fff;border:1px solid #65748a;width:100%}textarea{min-height:110px}button{background:#5a87fc;color:white;border:0;margin-top:10px;cursor:pointer}button:disabled{opacity:.5}#history{white-space:pre-wrap;overflow-wrap:anywhere}.msg{margin:10px 0;padding:12px;border-radius:9px;background:#293b53}.small{font-size:13px}</style></head><body><h1>⚡ NexusForge</h1><p>Mobile Orchestrierungsoberfläche mit automatischem LLM-Fallback.</p><section class="panel"><label>Server-Zugriffstoken (falls eingerichtet)<input id="token" type="password" autocomplete="off"></label><button id="connect">Verbindung prüfen</button><p class="small" id="status">Bereit</p></section><section class="panel"><div id="history" aria-live="polite"></div><label>Nachricht<textarea id="prompt" placeholder="Was soll NexusForge entwickeln?"></textarea></label><button id="send">Senden</button></section>
<script>
const $=id=>document.getElementById(id), messages=[];
$('token').value=sessionStorage.getItem('nf-token')||'';
async function request(path,body){let token=$('token').value;sessionStorage.setItem('nf-token',token);const res=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-NexusForge-Token':token},body:body?JSON.stringify(body):undefined});const json=await res.json();if(!res.ok)throw Error(json.error||'HTTP '+res.status);return json}
$('connect').onclick=async()=>{try{const d=await request('/api/providers');$('status').textContent=d.providers.length?d.providers.map(x=>x.name+' ('+x.model+')').join(' → '):'Keine API-Schlüssel eingerichtet';}catch(e){$('status').textContent=e.message}};
$('send').onclick=async()=>{const value=$('prompt').value.trim();if(!value)return;const btn=$('send');btn.disabled=true;const proposed=[...messages,{role:'user',content:value}];try{const d=await request('/api/chat',{messages:proposed});messages.push({role:'user',content:value},{role:'assistant',content:d.content});const box=document.createElement('div');box.className='msg';box.textContent='Du: '+value+'\n\n'+d.provider+': '+d.content;$('history').append(box);$('prompt').value='';$('status').textContent='Route: '+d.provider+' / '+d.model}catch(e){$('status').textContent='Fehler: '+e.message}finally{btn.disabled=false}};
</script></body></html>`
